    files: ["**/*.ts", "**/*.tsx"],
    languageOptions: {
      parser: typescriptParser,
      parserOptions: {
        project: "./tsconfig.json",
        tsconfigRootDir: import.meta.dirname,
        ecmaVersion: 2024,
        sourceType: "module",
      },
    },
    plugins: {
      ...(plugin.rules ? { traceability: plugin } : {}),
    },
    rules: {
      "@typescript-eslint/no-unused-vars": "error",
    },
  },
  {
    // JavaScript files
    files: ["**/*.js", "**/*.mjs"],
    languageOptions: {
      ecmaVersion: 2024,
      sourceType: "module",
    },
    plugins: {
      ...(plugin.rules ? { traceability: plugin } : {}),
    },
  },
  {
    // Test files
    files: [
      "**/*.test.{js,ts}",
      "**/__tests__/**/*.{js,ts}",
      "**/tests/**/*.{js,ts}",
    ],
    languageOptions: {
      globals: {
        describe: "readonly",
        it: "readonly",
        test: "readonly",
        expect: "readonly",
        beforeEach: "readonly",
        afterEach: "readonly",
        beforeAll: "readonly",
        afterAll: "readonly",
        jest: "readonly",
      },
    },
  },
  {
    // Ignore patterns
    ignores: [
      "lib/**",
      "dist/**",
      "build/**",
      "node_modules/**",
      "coverage/**",
