/**
 * ESLint Traceability Plugin
 * @story docs/stories/001.0-DEV-PLUGIN-SETUP.story.md
 * @req REQ-PLUGIN-STRUCTURE - Provide foundational plugin export and registration
 * @req REQ-ERROR-HANDLING - Gracefully handles plugin loading errors and missing dependencies
 */
import type { Rule } from "eslint";

/**
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINTENANCE-API-EXPORT - Expose maintenance utilities alongside core plugin exports
 */
import {
  detectStaleAnnotations,
  updateAnnotationReferences,
  batchUpdateAnnotations,
  verifyAnnotations,
  generateMaintenanceReport,
} from "./maintenance";

/**
 * @story docs/stories/002.0-DYNAMIC-RULE-LOADING.story.md
 * @req REQ-RULE-LIST - Enumerate supported rule file names for plugin discovery
 */
const RULE_NAMES = [
  "require-story-annotation",
  "require-req-annotation",
  "require-branch-annotation",
  "valid-annotation-format",
  "valid-story-reference",
  "valid-req-reference",
  "prefer-implements-annotation",
] as const;

type RuleName = (typeof RULE_NAMES)[number];

const rules: Record<RuleName, Rule.RuleModule> = {} as any;

RULE_NAMES.forEach(
  /**
   * @story docs/stories/002.0-DYNAMIC-RULE-LOADING.story.md
   * @req REQ-DYNAMIC-LOADING - Support dynamic rule loading by name at runtime
   * @param {RuleName} name - Rule file base name used to discover and load rule module
   */
  (name) => {
    /**
     * @story docs/stories/002.0-DYNAMIC-RULE-LOADING.story.md
     * @req REQ-DYNAMIC-LOADING - Support dynamic rule loading by name at runtime
     */
    try {
      /**
       * @story docs/stories/002.0-DYNAMIC-RULE-LOADING.story.md
       * @req REQ-DYNAMIC-LOADING - Support dynamic rule loading by name at runtime
       */
      // Dynamically require rule module
      const mod = require(`./rules/${name}`);
      // Support ESModule default export
      rules[name] = mod.default ?? mod;
    } catch (error: any) {
      /**
       * @story docs/stories/003.0-RULE-LOAD-ERROR-HANDLING.story.md
       * @req REQ-ERROR-HANDLING - Provide fallback rule module and surface errors when rule loading fails
       */
      /**
       * @story docs/stories/003.0-RULE-LOAD-ERROR-HANDLING.story.md
       * @req REQ-ERROR-HANDLING - Provide fallback rule module and surface errors when rule loading fails
       */
      console.error(
        `[eslint-plugin-traceability] Failed to load rule "${name}": ${error.message}`,
      );
      rules[name] = {
        meta: {
          type: "problem",
          docs: {
            description: `Failed to load rule '${name}'`,
          },
          schema: [],
        },
        create(context: Rule.RuleContext) {
          return {
            Program(node: any) {
              context.report({
                node,
                message: `eslint-plugin-traceability: Error loading rule "${name}": ${error.message}`,
              });
            },
          };
        },
      } as Rule.RuleModule;
    }
  },
);

const plugin: {
  rules: typeof rules;
  configs?: unknown;
  maintenance?: unknown;
} = {
  rules,
};

/**
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @req REQ-ERROR-SEVERITY - Map rule types to appropriate ESLint severity levels (errors vs warnings)
 * The recommended and strict configs treat missing annotations and missing references as errors,
 * while formatting issues are reported as warnings, matching the story's severity conventions.
 */
const TRACEABILITY_RULE_SEVERITIES: Readonly<Record<string, "error" | "warn">> =
  {
    "traceability/require-story-annotation": "error",
    "traceability/require-req-annotation": "error",
    "traceability/require-branch-annotation": "error",
    "traceability/valid-annotation-format": "warn",
    "traceability/valid-story-reference": "error",
    "traceability/valid-req-reference": "error",
  } as const;

/**
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @req REQ-PLUGIN-STRUCTURE - Provide foundational plugin export and registration
 * @req REQ-ERROR-SEVERITY - Map rule types to appropriate ESLint severity levels (errors vs warnings)
 * @story docs/stories/002.0-DEV-ESLINT-CONFIG.story.md
 * @req REQ-CONFIG-PRESETS - Provide flat-config presets that self-register the plugin and core rules
 */
function createTraceabilityFlatConfig() {
  return {
    rules: {
      ...TRACEABILITY_RULE_SEVERITIES,
    },
  };
}

/**
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @req REQ-ERROR-SEVERITY - Map rule types to appropriate ESLint severity levels (errors vs warnings)
 * The recommended and strict configs treat missing annotations and missing references as errors,
 * while formatting issues are reported as warnings, matching the story's severity conventions.
 */
const configs = {
  recommended: [createTraceabilityFlatConfig()],
  strict: [createTraceabilityFlatConfig()],
};

plugin.configs = configs;

/**
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-MAINTENANCE-API-EXPORT - Expose maintenance utilities alongside core plugin exports
 */
const maintenance = {
  detectStaleAnnotations,
  updateAnnotationReferences,
  batchUpdateAnnotations,
  verifyAnnotations,
  generateMaintenanceReport,
};

plugin.maintenance = maintenance;

export { rules, configs, maintenance };
export default plugin;

#!/usr/bin/env node
/**
 * Check for tracked CI artifacts in the repository.
 *
 * This script lists tracked files that live under any "ci/" directory
 * (matching a path segment of "ci/") but excludes any paths that
 * include ".voder/ci/".
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req 009.0
 */

"use strict";

const { execFileSync } = require("child_process");

function getTrackedFiles() {
  try {
    const out = execFileSync("git", ["ls-files"], { encoding: "utf8" });
    return out.split(/\r?\n/).filter(Boolean);
  } catch (err) {
    // If git is not available or the command fails, surface the error.
    console.error(
      "Failed to list tracked files with git ls-files:",
      err.message || err,
    );
    process.exit(1);
  }
}

function main() {
  const files = getTrackedFiles();

  // Match any path segment "ci/" (root or deeper), e.g. "ci/foo", "some/ci/bar"
  const ciPattern = /(^|\/)ci\//;
  const excludedSegment = ".voder/ci/";

  const matches = files.filter(
    (p) => ciPattern.test(p) && !p.includes(excludedSegment),
  );

  if (matches.length === 0) {
    // Nothing to report
    process.exit(0);
  }

  // Print report and fail with exit code 2
  console.error(
    'ERROR: Found tracked files under "ci/" (these should not be committed):',
  );
  for (const m of matches) {
    console.error("  -", m);
  }
  process.exit(2);
}

main();

/**
 * CI helper to run npm audit in JSON mode and write output to ci/npm-audit.json
 * @story docs/stories/012.0-DEV-CI-AUDIT-INTEGRATION.story.md
 * @req REQ-CI-AUDIT - Produce machine-readable npm audit reports for CI artifacts
 */
const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const res = spawnSync("npm", ["audit", "--json"], { encoding: "utf8" });
const outDir = path.join("ci");
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
const outPath = path.join(outDir, "npm-audit.json");
try {
  fs.writeFileSync(outPath, res.stdout || res.stderr || "", {
    encoding: "utf8",
  });
} catch (e) {
  console.error("Failed to write audit output", e);
}
process.exit(0);

/**
 * CI helper that runs dry-aged-deps (safety-like check) and writes ci/dry-aged-deps.json
 * @story docs/stories/012.0-DEV-CI-AUDIT-INTEGRATION.story.md
 * @req REQ-CI-SAFETY - Produce dry-aged-deps JSON output for CI artifacts non-failing
 */
const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");

// Use the locally installed dry-aged-deps via npm script for reproducible checks.
// On failure or missing output, emit a structured JSON error object instead of
// silently pretending there are zero packages.
let res = spawnSync("npm", ["run", "deps:maturity", "--", "--format=json"], {
  encoding: "utf8",
});

let output = res.stdout;
let hadError = false;

if (res.status !== 0 || !res.stdout) {
  hadError = true;
  const errorPayload = {
    status: "error",
    message: "dry-aged-deps failed",
    exitCode: typeof res.status === "number" ? res.status : null,
    stdout: res.stdout || null,
    stderr: res.stderr || null,
  };
  output = JSON.stringify(errorPayload, null, 2);
  console.error(
    "dry-aged-deps check failed; writing structured error object to CI artifact",
  );
}

const outDir = path.join("ci");
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
const outPath = path.join(outDir, "dry-aged-deps.json");

try {
  fs.writeFileSync(outPath, output || "", {
    encoding: "utf8",
  });
} catch (e) {
  console.error("Failed to write dry-aged-deps output", e);
}

// Ensure the output file is non-empty; if empty, write stdout/stderr or a fallback and warn.
// Prefer not to overwrite a structured error object that was just written.
try {
  const exists = fs.existsSync(outPath);
  const stats = exists ? fs.statSync(outPath) : null;
  const isEmpty = !exists || (stats && stats.size === 0);
  if (isEmpty) {
    const fallback =
      res.stdout ||
      res.stderr ||
      JSON.stringify({
        status: "error",
        message: "No output from dry-aged-deps and no stderr available",
      });
    try {
      fs.writeFileSync(outPath, fallback, { encoding: "utf8" });
      console.warn(
        "dry-aged-deps produced empty output; wrote fallback content to",
        outPath,
      );
    } catch (e) {
      console.error("Failed to write fallback dry-aged-deps output", e);
    }
  }
} catch (e) {
  console.error("Error while validating dry-aged-deps output file", e);
}

// Always exit 0 so CI does not fail on this auxiliary check.
process.exit(0);

const { spawnSync } = require("child_process");
const path = require("path");

const eslintPkgDir = path.dirname(require.resolve("eslint/package.json"));
const eslintCliPath = path.join(eslintPkgDir, "bin", "eslint.js");
const configPath = path.resolve(__dirname, "../eslint.config.js");

function run(code, rule) {
  const args = [
    "--no-config-lookup",
    "--config",
    configPath,
    "--stdin",
    "--stdin-filename",
    "foo.js",
    "--rule",
    "no-unused-vars:off",
