#!/usr/bin/env node
// Extract uncovered branch ranges from jest-coverage.json for files under src/rules/helpers
// @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
// @req REQ-COVERAGE-INSPECT - Produce checklist of uncovered branch locations to target with tests
const fs = require("fs");
const path = require("path");
const dataPath = path.join(process.cwd(), "jest-coverage.json");
if (!fs.existsSync(dataPath)) {
  console.error(
    "jest-coverage.json not found. Run npm test -- --coverage first.",
  );
  process.exit(2);
}
const raw = fs.readFileSync(dataPath, "utf8");
const json = JSON.parse(raw);
const cov = json.coverageMap || json.coverageMap || json.coverageMap;
const files = Object.keys(json.coverageMap || {});
const targetDir = path.join("src", "rules", "helpers");
const results = [];
for (const f of files) {
  if (!f.includes(targetDir)) continue;
  const entry = json.coverageMap[f];
  if (!entry) continue;
  const b = entry.b || {};
  const branchMap = entry.branchMap || {};
  const misses = [];
  for (const [k, arr] of Object.entries(b)) {
    const counts = arr;
    // counts might be array
    const anyZero = counts.some((c) => c === 0);
    if (anyZero) {
      const m = branchMap[k];
      if (m) {
        misses.push({ branchId: k, loc: m.loc, counts });
      } else {
        misses.push({ branchId: k, loc: null, counts });
      }
    }
  }
  results.push({ file: f, misses });
}
if (results.length === 0) {
  console.log("No helper files found in coverage map.");
  process.exit(0);
}
for (const r of results) {
  console.log("\nFile:", r.file);
  if (r.misses.length === 0) {
    console.log("  All branches covered. No misses.");
    continue;
  }
  for (const m of r.misses) {
    const loc = m.loc
      ? `${m.loc.start.line}:${m.loc.start.column}-${m.loc.end.line}:${m.loc.end.column}`
      : "unknown";
    console.log(
      `  Branch ${m.branchId} missed at ${loc} - counts: [${m.counts.join(",")}]`,
    );
  }
}
console.log("\nSummary:");
for (const r of results) {
  console.log(
    `- ${r.file} -> ${r.misses.length} branches with at least one missed path`,
  );
}

#!/usr/bin/env node
/**
 * Script to generate a JSON report of high-severity vulnerabilities in development dependencies.
 * @dev
 * @story docs/stories/012.0-DEV-CI-AUDIT-INTEGRATION.story.md
 * @story Generate a machine-readable npm audit report focused on development dependencies for CI.
 * @req REQ-CI-DEV-AUDIT
 * @req Run `npm audit --include=dev --audit-level=high --json`, capturing UTF-8 output focused on development
 *      dependencies, write to ci/npm-audit.json, ensure output directory exists, and always exit with code 0
 *      (do not block CI).
 */
const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");

// Run npm audit for dev dependencies with high threshold (omit production deps)
// Do not use shell: true
const result = spawnSync(
  "npm",
  ["audit", "--include=dev", "--audit-level=high", "--json"],
  {
    encoding: "utf8",
  },
);

// Ensure the output directory exists
const outputDir = path.join("ci");
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Determine content to write (prefer stdout, fall back to stderr)
const outputPath = path.join(outputDir, "npm-audit.json");
const content = result.stdout || result.stderr || "";

// Write the audit JSON to file, even if npm exits with non-zero status
try {
  fs.writeFileSync(outputPath, content, { encoding: "utf8" });
} catch (err) {
  // eslint-disable-next-line no-console -- ADR: docs/decisions/0001-ci-logging-and-reporting.md
  console.error("Failed to write npm audit output:", err);
}

// Exit zero regardless of vulnerabilities or errors to not block CI
process.exit(0);

