/**
 * @story As part of the build validation, we must ensure the built ESLint plugin
 *        actually exports a 'rules' object so downstream consumers (ESLint)
 *        can load and use the plugin rules.
 *
 * @req The built plugin artifact (as referenced by package.json "main" or
 *      commonly used output directories like dist/ or lib/) must be require()-able
 *      and must export an object with a 'rules' property whose value is an object.
 *
 * This script is non-interactive and will exit with a non-zero status code when
 * any check fails.
 */

const fs = require("fs");
const path = require("path");

function logError(...args) {
  console.error(...args);
}

function exitFailure(message, err) {
  if (message) logError("ERROR:", message);
  if (err) {
    if (err && err.stack) logError(err.stack);
    else logError(err);
  }
  process.exit(1);
}

function exitSuccess(message) {
  if (message) console.log(message);
  process.exit(0);
}

(function main() {
  const cwd = process.cwd();
  const pkgPath = path.join(cwd, "package.json");
  const tried = [];
  let candidates = [];

  // Try package.json main first if present
  if (fs.existsSync(pkgPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
      if (pkg && pkg.main) {
        candidates.push(path.join(cwd, pkg.main));
      }
    } catch (err) {
      // ignore parse errors; will try other common paths
    }
  }

  // Common build output locations
  candidates = candidates.concat([
    path.join(cwd, "dist", "index.js"),
    path.join(cwd, "dist"),
    path.join(cwd, "lib", "index.js"),
    path.join(cwd, "lib"),
    path.join(cwd, "index.js"),
    path.join(cwd, "build", "index.js"),
    path.join(cwd, "build"),
  ]);

  let lastError = null;
  let plugin;
  let usedPath;

  for (const candidate of candidates) {
    tried.push(candidate);
    if (!fs.existsSync(candidate)) {
      lastError = new Error(`Path does not exist: ${candidate}`);
      continue;
    }
    try {
      // Use require with resolved path to ensure Node module resolution works
      const resolved = require.resolve(candidate);
      usedPath = resolved;
      // eslint-disable-next-line import/no-dynamic-require, global-require -- See ADR: docs/decisions/0001-allow-dynamic-require-for-built-plugins.md
      plugin = require(resolved);
      break;
    } catch (err) {
      lastError = err;
      // continue trying other candidates
    }
  }

  if (!plugin) {
    exitFailure(
      "Failed to require built plugin. Tried the following locations:\n" +
        tried.join("\n"),
      lastError,
    );
  }

  // Support ES module transpiles that export via default
  if (
    plugin &&
    plugin.__esModule &&
    Object.prototype.hasOwnProperty.call(plugin, "default")
  ) {
    plugin = plugin.default;
  }

  if (!plugin || typeof plugin !== "object") {
    exitFailure(
      `Plugin did not export an object. Found type: ${plugin === null ? "null" : typeof plugin}`,
    );
  }

  if (!Object.prototype.hasOwnProperty.call(plugin, "rules")) {
    exitFailure("Plugin does not export a 'rules' property.");
  }

  const rules = plugin.rules;
  if (!rules || typeof rules !== "object" || Array.isArray(rules)) {
    const type =
      rules === null ? "null" : Array.isArray(rules) ? "array" : typeof rules;
    exitFailure(`Plugin 'rules' is not an object. Found type: ${type}`);
  }

  // All checks passed
  exitSuccess(
    `OK: Plugin exports 'rules' object. (${usedPath || "resolved module"})`,
  );
})();

#!/usr/bin/env node
/**
 * @story Provide a lightweight guard that runs the lint plugin check script.
 * @req Execute scripts/lint-plugin-check.js and exit with its status.
 */

const { spawnSync } = require("child_process");
const path = require("path");

const scriptPath = path.join(__dirname, "lint-plugin-check.js");

// Run the check script using the same Node.js executable, forwarding any CLI args and stdio.
const result = spawnSync(
  process.execPath,
  [scriptPath, ...process.argv.slice(2)],
  {
    stdio: "inherit",
  },
);

// If spawnSync failed to start the process, surface the error and exit non-zero.
if (result.error) {
  // eslint-disable-next-line no-console -- Logging is required here for CLI error visibility; see docs/decisions/adr-0001-console-usage-for-cli-guards.md
  console.error("Failed to run lint-plugin-check.js:", result.error);
  process.exit(1);
}

// If the child was terminated by a signal, propagate the signal to this process.
if (result.signal) {
  try {
    process.kill(process.pid, result.signal);
  } catch (e) {
    // If we cannot re-emit the signal, exit with code 1.
    process.exit(1);
  }
}

// Otherwise exit with the child's exit status (0, non-zero).
process.exit(result.status === null ? 1 : result.status);

#!/usr/bin/env node
/**
 * Scan the repository for ESLint/TypeScript suppression comments and generate a
 * parseable markdown report at scripts/eslint-suppressions-report.md.
 *
 * This script excludes node_modules, .git, lib, dist, out, .voder directories.
 * It searches source files with extensions: .js, .cjs, .mjs, .ts, .tsx, .jsx
 *
 * Exit codes:
 *  0 - no suppressions found
 *  2 - suppressions found (report written)
 *
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-REPORT-ESLINT-SUPPRESSIONS - Provide a machine-readable report of suppression comments
 */

const fs = require("fs");
const path = require("path");

const root = process.cwd();
const outPath = path.join("scripts", "eslint-suppressions-report.md");

const exts = new Set([".js", ".cjs", ".mjs", ".ts", ".tsx", ".jsx"]);
const excludedDirs = new Set([
  "node_modules",
  ".git",
  "lib",
  "dist",
  "out",
  ".voder",
  "coverage",
]);

const patterns = [
  {
    name: "eslint-disable",
    regex: /\/\*\s*eslint-disable(?:\s|\*|$)/,
    type: "block",
  },
  {
    name: "eslint-disable-line",
    regex: /\/\/\s*eslint-disable-line/,
    type: "line",
  },
  {
    name: "eslint-disable-next-line",
    regex: /\/\/\s*eslint-disable-next-line/,
    type: "line",
  },
  { name: "ts-nocheck", regex: /\/\/\s*@ts-nocheck/, type: "line" },
  { name: "ts-ignore", regex: /\/\/\s*@ts-ignore/, type: "line" },
  {
    name: "eslint-disable-file",
    regex: /\/\*\s*eslint-disable\s*$/,
    type: "block",
  },
];

function walk(dir, cb) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (excludedDirs.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, cb);
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name).toLowerCase();
      if (exts.has(ext)) cb(full);
    }
  }
}

function hasJustification(text) {
  if (!text) return false;
  if (text.indexOf(" -- ") !== -1) return true;
  if (/justification/i.test(text)) return true;
  if (/ADR/i.test(text)) return true;
  if (text.indexOf("docs/decisions/") !== -1) return true;
  return false;
}

function scanFile(filePath) {
  const content = fs.readFileSync(filePath, "utf8");
  const lines = content.split(/\r?\n/);
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const p of patterns) {
      if (p.regex.test(line)) {
        if (hasJustification(line)) continue;
        hits.push({
          filePath,
          line: i + 1,
          text: line.trim(),
          pattern: p.name,
        });
      }
    }
  }

  // Also search for block comments that may span multiple lines (/* eslint-disable */)
  // We'll search the full file for the exact token
  const blockRegex = /\/\*[\s\S]*?\*\//g;
  let m;
  while ((m = blockRegex.exec(content)) !== null) {
    const block = m[0];
    const idx = m.index;
    if (/eslint-disable/.test(block)) {
      // compute line number
      const prefix = content.slice(0, idx);
      const lineNumber = prefix.split(/\r?\n/).length;
      const firstLine = block.split(/\r?\n/)[0].trim();
      if (hasJustification(firstLine)) continue;
      hits.push({
        filePath,
        line: lineNumber,
        text: firstLine,
        pattern: "eslint-disable-block",
      });
    }
  }

  return hits;
}

const results = [];
walk(root, (file) => {
  try {
    const rel = path.relative(root, file);
    // skip files under scripts/eslint-suppressions-report.md output
    if (rel === outPath) return;
    // skip this script itself
    if (rel === path.join("scripts", "report-eslint-suppressions.js")) return;
    const fileHits = scanFile(file);
    if (fileHits.length) results.push(...fileHits);
  } catch (err) {
    // ignore unreadable files
  }
});

function remediationSuggestion(hit) {
  switch (hit.pattern) {
    case "eslint-disable":
    case "eslint-disable-block":
      return 'Avoid broad block-level "eslint-disable". Narrow to the specific rule(s) and add a one-line justification comment referencing an issue or ADR, or refactor code to satisfy the rule.';
    case "eslint-disable-line":
    case "eslint-disable-next-line":
      return "Prefer refactoring to avoid the rule violation or narrow the disable to the specific rule. Add a one-line justification comment referencing an issue/ADR if suppression is unavoidable.";
    case "ts-nocheck":
      return "Remove @ts-nocheck and fix TypeScript errors. If temporary, replace with targeted @ts-expect-error with justification and comment pointing to an issue.";
    case "ts-ignore":
      return "Replace @ts-ignore with a targeted @ts-expect-error and a one-line justification comment referencing an issue/ADR. Fix underlying types when possible.";
    default:
      return "Review this suppression and either remove it, narrow its scope, or add a justification comment referencing an issue or ADR.";
  }
}

const outLines = [];
outLines.push("# ESLint / TypeScript Suppressions Report");
outLines.push(`Generated: ${new Date().toISOString()}`);
outLines.push("");
if (results.length === 0) {
  outLines.push("No suppressions found.");
  fs.writeFileSync(outPath, outLines.join("\n"), "utf8");
  console.log("No suppressions found. Report written to", outPath);
  process.exit(0);
}

outLines.push(`Total suppressions found: ${results.length}`);
outLines.push("");
outLines.push("## Suppressions");
for (const r of results) {
  outLines.push("- **" + r.filePath + ":" + r.line + "**");
  outLines.push("  - Suppression: `" + r.text.replace(/`/g, "\\`") + "`");
  outLines.push("  - Pattern: " + r.pattern);
  outLines.push("  - Suggested remediation: " + remediationSuggestion(r));
  outLines.push("");
}

fs.writeFileSync(outPath, outLines.join("\n"), "utf8");
console.log(
  `${results.length} suppressions found. Report written to ${outPath}`,
);
process.exit(2);

#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const ts = require("typescript");

function walkDir(dir, fileList = []) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      // skip node_modules, .git, lib, dist
      if (["node_modules", ".git", "lib", "dist", "out"].includes(entry.name))
        continue;
      walkDir(full, fileList);
    } else if (entry.isFile() && full.endsWith(".ts")) {
      fileList.push(full);
    }
  }
  return fileList;
}

function getLeadingCommentText(sourceText, node) {
  const texts = [];
  // jsDoc nodes
  if (node.jsDoc && node.jsDoc.length) {
    for (const jd of node.jsDoc) {
      texts.push(sourceText.slice(jd.pos, jd.end));
    }
  }
  // leading comments
  const pos = node.getFullStart ? node.getFullStart() : node.pos;
  const ranges = ts.getLeadingCommentRanges(sourceText, pos) || [];
  for (const r of ranges) {
    texts.push(sourceText.slice(r.pos, r.end));
  }
  return texts.join("\n");
}

function checkFile(filePath) {
  const sourceText = fs.readFileSync(filePath, "utf8");
  const sourceFile = ts.createSourceFile(
    filePath,
    sourceText,
    ts.ScriptTarget.Latest,
    /*setParentNodes*/ true,
  );

  // compute file-level leading comments
  const fileLeadingRanges = ts.getLeadingCommentRanges(sourceText, 0) || [];
  let fileLeadingText = "";
  for (const r of fileLeadingRanges) {
    fileLeadingText += sourceText.slice(r.pos, r.end) + "\n";
  }
  const fileHasStory = /@story\b/.test(fileLeadingText);
  const fileHasReq = /@req\b/.test(fileLeadingText);

  const functions = [];
  const branches = [];

  function visit(node) {
    switch (node.kind) {
      case ts.SyntaxKind.FunctionDeclaration:
      case ts.SyntaxKind.FunctionExpression:
      case ts.SyntaxKind.ArrowFunction:
      case ts.SyntaxKind.MethodDeclaration:
      case ts.SyntaxKind.MethodSignature:
      case ts.SyntaxKind.InterfaceDeclaration:
      case ts.SyntaxKind.VariableStatement:
        // We'll handle functions specifically
        break;
      default:
        break;
    }

    // Identify function-like nodes
    if (
      node.kind === ts.SyntaxKind.FunctionDeclaration ||
      node.kind === ts.SyntaxKind.FunctionExpression ||
      node.kind === ts.SyntaxKind.ArrowFunction ||
      node.kind === ts.SyntaxKind.MethodDeclaration ||
      node.kind === ts.SyntaxKind.MethodSignature
    ) {
      const leading = getLeadingCommentText(sourceText, node);
      let hasStory = /@story\b/.test(leading);
      let hasReq = /@req\b/.test(leading);

      // consider file-level annotations as satisfying node annotations
      hasStory = hasStory || fileHasStory;
      hasReq = hasReq || fileHasReq;

      let name = "<unknown>";
      try {
        if (node.name && node.name.escapedText) name = node.name.escapedText;
        else if (
          node.parent &&
          node.parent.kind === ts.SyntaxKind.VariableDeclaration &&
          node.parent.name &&
          node.parent.name.escapedText
        )
          name = node.parent.name.escapedText;
        else if (
          node.kind === ts.SyntaxKind.MethodDeclaration &&
          node.name &&
          node.name.getText
        )
          name = node.name.getText(sourceFile);
      } catch (e) {
        // ignore
      }

      const pos = sourceFile.getLineAndCharacterOfPosition(
        node.getStart(sourceFile, false),
      );
      functions.push({
        filePath,
        line: pos.line + 1,
        name,
        kind: ts.SyntaxKind[node.kind],
        hasStory,
        hasReq,
      });
    }

    // Identify branches
    if (
      node.kind === ts.SyntaxKind.IfStatement ||
      node.kind === ts.SyntaxKind.SwitchStatement ||
      node.kind === ts.SyntaxKind.CaseClause ||
      node.kind === ts.SyntaxKind.TryStatement ||
      node.kind === ts.SyntaxKind.CatchClause ||
      node.kind === ts.SyntaxKind.ForStatement ||
      node.kind === ts.SyntaxKind.ForOfStatement ||
      node.kind === ts.SyntaxKind.ForInStatement ||
      node.kind === ts.SyntaxKind.WhileStatement ||
      node.kind === ts.SyntaxKind.DoStatement
    ) {
      const leading = getLeadingCommentText(sourceText, node);
      let hasStory = /@story\b/.test(leading);
      let hasReq = /@req\b/.test(leading);

      // consider file-level annotations as satisfying branch annotations
      hasStory = hasStory || fileHasStory;
      hasReq = hasReq || fileHasReq;

      const pos = sourceFile.getLineAndCharacterOfPosition(
        node.getStart(sourceFile, false),
      );
      branches.push({
        filePath,
        line: pos.line + 1,
        kind: ts.SyntaxKind[node.kind],
        hasStory,
        hasReq,
      });
    }

    ts.forEachChild(node, visit);
  }

  visit(sourceFile);

  const missingFunctions = functions.filter((f) => !(f.hasStory && f.hasReq));
  const missingBranches = branches.filter((b) => !(b.hasStory && b.hasReq));

  return { missingFunctions, missingBranches };
}

function main() {
  const baseDir = path.resolve(process.cwd(), "src");
  if (!fs.existsSync(baseDir)) {
    console.error("src directory not found");
    process.exit(1);
  }

  const files = walkDir(baseDir);
  const report = [];
  const missingFunctionsAll = [];
  const missingBranchesAll = [];

  for (const f of files) {
    const res = checkFile(f);
    if (res.missingFunctions.length > 0)
      missingFunctionsAll.push(...res.missingFunctions);
    if (res.missingBranches.length > 0)
      missingBranchesAll.push(...res.missingBranches);
  }

  const outLines = [];
  outLines.push("# Traceability Report");
  outLines.push("Generated by scripts/traceability-check.js");
  outLines.push("");

  outLines.push("## Summary");
  outLines.push(`Files scanned: ${files.length}`);
  outLines.push(`Functions missing annotations: ${missingFunctionsAll.length}`);
  outLines.push(`Branches missing annotations: ${missingBranchesAll.length}`);
  outLines.push("");

  if (missingFunctionsAll.length > 0) {
    outLines.push("## Functions missing @story/@req");
    for (const f of missingFunctionsAll) {
      const missing = [];
      if (!f.hasStory) missing.push("@story");
      if (!f.hasReq) missing.push("@req");
      outLines.push(
        `- ${f.filePath}:${f.line} - ${f.kind} '${f.name}' - missing: ${missing.join(", ")}`,
      );
    }
    outLines.push("");
  }

  if (missingBranchesAll.length > 0) {
    outLines.push("## Branches missing @story/@req");
    for (const b of missingBranchesAll) {
      const missing = [];
      if (!b.hasStory) missing.push("@story");
      if (!b.hasReq) missing.push("@req");
      outLines.push(
        `- ${b.filePath}:${b.line} - ${b.kind} - missing: ${missing.join(", ")}`,
      );
    }
    outLines.push("");
  }

  const out = outLines.join("\n");
  fs.writeFileSync(path.join("scripts", "traceability-report.md"), out, "utf8");
  console.log("Traceability report written to scripts/traceability-report.md");
}

main();

#!/usr/bin/env node
/**
 * Validate that scripts/ directory files are not empty or placeholder-only.
 * @story docs/stories/009.0-DEV-MAINTENANCE-TOOLS.story.md
 * @req REQ-VALIDATE-SCRIPTS-NONEMPTY - Prevent zero-byte or comment-only placeholder scripts in scripts/ directory
 *
 * Exits with a non-zero exit code when any problematic files are found.
 */

const fs = require("fs");
const path = require("path");

function isCommentOrWhitespaceOnly(content) {
  // Remove shebang if present
  if (content.startsWith("#!")) {
    const idx = content.indexOf("\n");
    if (idx === -1) content = "";
    else content = content.slice(idx + 1);
  }

  // Remove block comments
  content = content.replace(/\/\*[\s\S]*?\*\//g, "");
  // Remove line comments
  content = content.replace(/\/\/.*$/gm, "");
  // Remove whitespace
  content = content.replace(/\s+/g, "");
  return content.length === 0;
}

function main() {
  const scriptsDir = path.join(process.cwd(), "scripts");
  if (!fs.existsSync(scriptsDir) || !fs.statSync(scriptsDir).isDirectory()) {
    console.error("ERROR: scripts/ directory does not exist");
    process.exit(2);
  }

  const files = fs.readdirSync(scriptsDir);
  const problems = [];

  for (const f of files) {
    const fp = path.join(scriptsDir, f);
    const stat = fs.statSync(fp);
    if (stat.isDirectory()) continue;

    const raw = fs.readFileSync(fp, "utf8");
    if (stat.size === 0) {
      problems.push({ file: fp, reason: "zero-length file" });
      continue;
    }

    if (isCommentOrWhitespaceOnly(raw)) {
      problems.push({
        file: fp,
        reason: "comment-or-whitespace-only (likely placeholder)",
      });
      continue;
    }

    // Detect obviously placeholder text
    const placeholderPatterns = [/\bTODO\b/i, /\bPLACEHOLDER\b/i, /\bSTUB\b/i];
    for (const pat of placeholderPatterns) {
      if (pat.test(raw) && raw.trim().length < 200) {
        problems.push({
          file: fp,
          reason: `contains placeholder token (${pat})`,
        });
        break;
      }
    }
  }

  if (problems.length > 0) {
    console.error("Found placeholder or empty scripts in scripts/:");
    for (const p of problems) {
      console.error(` - ${p.file}: ${p.reason}`);
    }
    console.error(
      "\nPlease replace these with functional scripts or remove them.",
    );
    process.exit(1);
  }

  console.log("OK: scripts/ files appear non-empty and non-placeholder.");
  process.exit(0);
}

main();

