/* eslint-env node */
/**
 * Rule to validate @story annotation references refer to existing story files
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-PATH-RESOLUTION - Resolve relative paths correctly and enforce configuration
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
 */
import type { Rule } from "eslint";
import {
  normalizeStoryPath,
  hasValidExtension,
} from "../utils/storyReferenceUtils";
import {
  performSecurityValidations,
  handleProjectBoundaryForExistence,
} from "./helpers/valid-story-reference-helpers";

const defaultStoryDirs = ["docs/stories", "stories"];

/**
 * Shared helper to report an invalid story path. Centralizes the
 * `invalidPath` diagnostic so callers don't repeat the same
 * `context.report` shape.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PROJECT-BOUNDARY - Ensure resolved candidate paths remain within the project root
 * @req REQ-ERROR-CONSISTENCY - Maintain a consistent template for invalid path diagnostics across rules
 */
function reportInvalidPath(opts: {
  storyPath: string;
  commentNode: any;
  context: any;
}): void {
  const { storyPath, commentNode, context } = opts;
  context.report({
    node: commentNode,
    messageId: "invalidPath",
    data: { path: storyPath },
  });
}

/**
 * Extract the story path from the annotation line and delegate validation.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-ANNOTATION-VALIDATION - Ensure each annotation line is parsed
 */
function validateStoryPath(opts: {
  line: string;
  commentNode: any;
  context: any;
  cwd: string;
  storyDirs: string[];
  allowAbsolute: boolean;
  requireExt: boolean;
}): void {
  const {
    line,
    commentNode,
    context,
    cwd,
    storyDirs,
    allowAbsolute,
    requireExt,
  } = opts;
  const parts = line.split(/\s+/);
  const storyPath = parts[1];
  if (!storyPath) return;
  processStoryPath({
    storyPath,
    commentNode,
    context,
    cwd,
    storyDirs,
    allowAbsolute,
    requireExt,
  });
}

/**
 * Handle existence status and report appropriate diagnostics for missing
 * or filesystem-error conditions, assuming project-boundary checks have
 * already been applied.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Ensure referenced files exist
 * @req REQ-ERROR-HANDLING - Differentiate missing files from filesystem errors
 */
function reportExistenceStatus(
  existenceResult: ReturnType<typeof normalizeStoryPath>["existence"],
  storyPath: string,
  commentNode: any,
  context: any,
): void {
  if (!existenceResult || existenceResult.status === "exists") {
    return;
  }

  if (existenceResult.status === "missing") {
    context.report({
      node: commentNode,
      messageId: "fileMissing",
      data: { path: storyPath },
    });
    return;
  }

  if (existenceResult.status === "fs-error") {
    const rawError = existenceResult.error;
    let errorMessage: string;

    if (rawError == null) {
      errorMessage = "Unknown filesystem error";
    } else if (rawError instanceof Error) {
      errorMessage = rawError.message;
    } else {
      errorMessage = String(rawError);
    }

    context.report({
      node: commentNode,
      messageId: "fileAccessError",
      data: {
        path: storyPath,
        error: errorMessage,
      },
    });
  }
}

/**
 * Report any problems related to the existence or accessibility of the
 * referenced story file. Filesystem and I/O errors are surfaced with a
 * dedicated diagnostic that differentiates them from missing files.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Ensure referenced files exist
 * @req REQ-ERROR-HANDLING - Differentiate missing files from filesystem errors
 * @req REQ-PROJECT-BOUNDARY - Ensure resolved candidate paths remain within the project root
 * @req REQ-CONFIGURABLE-PATHS - Respect configured storyDirectories while enforcing project boundaries
 */
function reportExistenceProblems(opts: {
  storyPath: string;
  commentNode: any;
  context: any;
  cwd: string;
  storyDirs: string[];
}): void {
  const { storyPath, commentNode, context, cwd, storyDirs } = opts;

  const result = normalizeStoryPath(storyPath, cwd, storyDirs);
  const existenceResult = result.existence;

  const candidates = result.candidates || [];

  const invalidByBoundary = handleProjectBoundaryForExistence({
    storyPath,
    commentNode,
    context,
    cwd,
    candidates,
    existenceResult,
    reportInvalidPath,
  });

  if (invalidByBoundary) {
    return;
  }

  reportExistenceStatus(existenceResult, storyPath, commentNode, context);
}

/**
 * Process and validate the story path for security, extension, and existence.
 * Filesystem and I/O errors are handled inside the underlying utilities
 * (e.g. storyExists) and surfaced as missing-file or filesystem-error
 * diagnostics where appropriate.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-PATH-RESOLUTION - Resolve relative paths correctly and enforce configuration
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
 * @req REQ-ERROR-HANDLING - Delegate filesystem and I/O error handling to utilities and differentiate error types
 */
function processStoryPath(opts: {
  storyPath: string;
  commentNode: any;
  context: any;
  cwd: string;
  storyDirs: string[];
  allowAbsolute: boolean;
  requireExt: boolean;
}): void {
  const {
    storyPath,
    commentNode,
    context,
    cwd,
    storyDirs,
    allowAbsolute,
    requireExt,
  } = opts;

  const securityOk = performSecurityValidations({
    storyPath,
    commentNode,
    context,
    cwd,
    allowAbsolute,
    reportInvalidPath,
  });

  if (!securityOk) {
    return;
  }

  // Extension check
  if (requireExt && !hasValidExtension(storyPath)) {
    context.report({
      node: commentNode,
      messageId: "invalidExtension",
      data: { path: storyPath },
    });
    return;
  }

  /**
   * Existence check:
   * - Distinguish between missing files and filesystem errors.
   * - Filesystem and I/O errors are surfaced with a dedicated diagnostic.
   *
   * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
   * @req REQ-FILE-EXISTENCE - Ensure referenced files exist
   * @req REQ-ERROR-HANDLING - Differentiate missing files from filesystem errors
   */
  reportExistenceProblems({
    storyPath,
    commentNode,
    context,
    cwd,
    storyDirs,
  });
}

/**
 * Handle a single comment node by processing its lines.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-ANNOTATION-VALIDATION - Ensure each annotation line is parsed
 */
function handleComment(opts: {
  commentNode: any;
  context: any;
  cwd: string;
  storyDirs: string[];
  allowAbsolute: boolean;
  requireExt: boolean;
}): void {
  const { commentNode, context, cwd, storyDirs, allowAbsolute, requireExt } =
    opts;
  const lines = commentNode.value
    .split(/\r?\n/)
    /**
     * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
     * @req REQ-ANNOTATION-VALIDATION - Ensure each annotation line is parsed
     */
    .map((l: string) => l.replace(/^[^@]*/, "").trim());
  for (const line of lines) {
    if (line.startsWith("@story")) {
      validateStoryPath({
        line,
        commentNode,
        context,
        cwd,
        storyDirs,
        allowAbsolute,
        requireExt,
      });
    }
  }
}

