import { getNodeName } from "../rules/helpers/require-story-utils";
import { hasReqAnnotation } from "./reqAnnotationDetection";

/**
 * Helper to retrieve the JSDoc comment for a node.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-GET-JSDOC - Retrieve JSDoc comment for a node
 */
function getJsdocComment(sourceCode: any, node: any) {
  return sourceCode.getJSDocComment(node);
}

/**
 * Helper to retrieve leading comments from a node (TypeScript declare style).
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-LEADING-COMMENTS - Collect leading comments from node
 */
function getLeadingComments(node: any) {
  return (node as any).leadingComments || [];
}

/**
 * Helper to retrieve comments before a node using the sourceCode API.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-COMMENTS-BEFORE - Collect comments before node via sourceCode
 */
function getCommentsBefore(sourceCode: any, node: any) {
  return sourceCode.getCommentsBefore(node) || [];
}

/**
 * Helper to combine leading and before comments into a single array.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-COMBINE-COMMENTS - Combine comment arrays for checking
 */
function combineComments(leading: any[], before: any[]) {
  return [...leading, ...before];
}

/**
 * Determine the most appropriate node to attach an inserted JSDoc to.
 * Prefers outer function-like constructs such as methods, variable declarators,
 * or wrapping expression statements for function expressions.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-AUTOFIX - Provide autofix for missing @req annotation
 */
function getFixTargetNode(node: any) {
  const parent = node && (node as any).parent;

  // When there is no parent, attach the annotation directly to the node itself.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-AUTOFIX - Default to annotating the node when it has no parent
  if (!parent) {
    return node;
  }

  // If the node is part of a class/obj method definition, attach to the MethodDefinition
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-AUTOFIX - Attach fixes to the MethodDefinition wrapper for methods
  if (parent.type === "MethodDefinition") {
    return parent;
  }

  // If the node is the init of a variable declarator, attach to the VariableDeclarator
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-AUTOFIX - Attach fixes to the VariableDeclarator for function initializers
  if (parent.type === "VariableDeclarator" && parent.init === node) {
    return parent;
  }

  // If the parent is an expression statement (e.g. IIFE or assigned via expression),
  // attach to the outer ExpressionStatement.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-AUTOFIX - Attach fixes to the ExpressionStatement wrapper for IIFEs
  if (parent.type === "ExpressionStatement") {
    return parent;
  }

  return node;
}

/**
 * Creates a fix function that inserts a missing @req JSDoc before the node.
 * Returned function is a proper named function so no inline arrow is used.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-AUTOFIX - Provide autofix for missing @req annotation
 */
function createMissingReqFix(node: any) {
  const target = getFixTargetNode(node);
  /**
   * Fixer used to insert a default @req annotation before the chosen target node.
   * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
   * @req REQ-ANNOTATION-AUTOFIX - Provide autofix for missing @req annotation
   */
  return function missingReqFix(fixer: any) {
    return fixer.insertTextBefore(target, "/** @req <REQ-ID> */\n");
  };
}

/**
 * Helper to report a missing @req annotation via the ESLint context API.
 * Uses getNodeName to provide a readable name for the node.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/007.0-DEV-ERROR-REPORTING.story.md
 * @req REQ-ANNOTATION-REPORTING - Report missing @req annotation to context
 * @req REQ-ERROR-SPECIFIC - Provide specific error details including node name
 * @req REQ-ERROR-LOCATION - Include contextual location information in errors
 * @req REQ-ERROR-SUGGESTION - Provide actionable suggestions or fixes where possible
 * @req REQ-ERROR-CONTEXT - Include contextual hints to help understand the error
 */
function reportMissing(context: any, node: any, enableFix: boolean = true) {
  const rawName =
    getNodeName(node) ?? (node && getNodeName((node as any).parent));
  const name = rawName ?? "(anonymous)";
  const nameNode =
    (node && (node as any).id && (node as any).id.type === "Identifier"
      ? (node as any).id
      : node && (node as any).key && (node as any).key.type === "Identifier"
        ? (node as any).key
        : node) ?? node;
  const reportOptions: any = {
    node: nameNode,
    messageId: "missingReq",
    data: { name, functionName: name },
  };

  // Conditionally attach an autofix only when enabled in the rule options.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-AUTOFIX - Only provide autofix suggestions when explicitly enabled
  if (enableFix) {
    reportOptions.fix = createMissingReqFix(node);
  }

  context.report(reportOptions);
}

/**
 * Helper to check @req annotation presence on TS declare functions and method signatures.
 * This helper is intentionally scope/exportPriority agnostic and focuses solely
 * on detection and reporting of @req annotations for the given node.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-TYPESCRIPT-SUPPORT - Support TypeScript-specific function syntax
 * @req REQ-ANNOTATION-REQ-DETECTION - Determine presence of @req annotation
 * @req REQ-ANNOTATION-REPORTING - Report missing @req annotation to context
 * @param context - ESLint rule context used to obtain source and report problems
 * @param node - Function-like AST node whose surrounding comments should be inspected
 * @param options - Optional configuration controlling behaviour (e.g., enableFix)
 * @returns void
 */
export function checkReqAnnotation(
  context: any,
  node: any,
  options?: { enableFix?: boolean },
) {
  const { enableFix = true } = options ?? {};
  const sourceCode = context.getSourceCode();
  const jsdoc = getJsdocComment(sourceCode, node);
  const leading = getLeadingComments(node);
  const comments = getCommentsBefore(sourceCode, node);
  const all = combineComments(leading, comments);
  const hasReq = hasReqAnnotation(jsdoc, all, context, node);
  // BRANCH when a @req annotation is missing and must be reported
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION
  // @req REQ-ANNOTATION-REPORTING
  if (!hasReq) {
    reportMissing(context, node, enableFix);
  }
}

import type { Rule } from "eslint";
const PRE_COMMENT_OFFSET = 2; // number of lines above branch to inspect for comments

/**
 * Valid branch types for require-branch-annotation rule.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-SIGNIFICANCE-CRITERIA - Define criteria for which branches require annotations
 */
export const DEFAULT_BRANCH_TYPES = [
  "IfStatement",
  "SwitchCase",
  "TryStatement",
  "CatchClause",
  "ForStatement",
  "ForOfStatement",
  "ForInStatement",
  "WhileStatement",
  "DoWhileStatement",
] as const;

/**
 * Type for branch nodes supported by require-branch-annotation rule.
 */
export type BranchType = (typeof DEFAULT_BRANCH_TYPES)[number];

/**
 * Validate branchTypes configuration option and return branch types to enforce,
 * or return an ESLint listener if configuration is invalid.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-CONFIGURABLE-SCOPE - Allow configuration of branch types for annotation enforcement
 */
export function validateBranchTypes(
  context: Rule.RuleContext,
): BranchType[] | Rule.RuleListener {
  const options: any = context.options[0] || {};

  /**
   * Conditional branch checking whether branchTypes option was provided.
   * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
   * @req REQ-TRACEABILITY-CONDITIONAL - Trace configuration branch existence check
   */
  if (Array.isArray(options.branchTypes)) {
    /**
     * Predicate to determine whether a provided branch type is invalid.
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-TRACEABILITY-FILTER-CALLBACK - Trace filter callback for invalid branch type detection
     */
    function isInvalidType(t: any): boolean {
      return !DEFAULT_BRANCH_TYPES.includes(t as BranchType);
    }

    const invalidTypes = options.branchTypes.filter(isInvalidType);
    /**
     * Conditional branch checking whether any invalid types were found.
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-TRACEABILITY-INVALID-DETECTION - Trace handling when invalid types are detected
     */
    if (invalidTypes.length > 0) {
      /**
       * Program listener produced when configuration is invalid.
       * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
       * @req REQ-TRACEABILITY-PROGRAM-LISTENER - Trace Program listener reporting invalid config values
       */
      function ProgramHandler(node: any) {
        /**
         * Report a single invalid type for the given Program node.
         * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
         * @req REQ-TRACEABILITY-FOR-EACH-CALLBACK - Trace reporting for each invalid type
         */
        function reportInvalidType(t: any) {
          context.report({
            node,
            message: `Value "${t}" should be equal to one of the allowed values: ${DEFAULT_BRANCH_TYPES.join(
              ", ",
            )}`,
          });
        }
        invalidTypes.forEach(reportInvalidType);
      }
      return { Program: ProgramHandler };
    }
  }

  return Array.isArray(options.branchTypes)
    ? (options.branchTypes as BranchType[])
    : Array.from(DEFAULT_BRANCH_TYPES);
}

/**
 * Gather leading comment text for a branch node.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-COMMENT-ASSOCIATION - Associate inline comments with their corresponding code branches
 */
export function gatherBranchCommentText(
  sourceCode: ReturnType<Rule.RuleContext["getSourceCode"]>,
  node: any,
): string {
  /**
   * Conditional branch for SwitchCase nodes that may include inline comments.
   * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
   * @req REQ-TRACEABILITY-SWITCHCASE-COMMENTS - Trace collection of preceding comments for SwitchCase
   */
  if (node.type === "SwitchCase") {
    const lines = sourceCode.lines;
    const startLine = node.loc.start.line;
    let i = startLine - PRE_COMMENT_OFFSET;
    const comments: string[] = [];
    // @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
    // @req REQ-TRACEABILITY-WHILE - Trace while loop that collects preceding comments for SwitchCase
    while (i >= 0 && /^\s*(\/\/|\/\*)/.test(lines[i])) {
      comments.unshift(lines[i].trim());
      i--;
    }
    return comments.join(" ");
  }
  const comments = sourceCode.getCommentsBefore(node) || [];

  /**
   * Mapper to extract the text value from a comment node.
   * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
   * @req REQ-TRACEABILITY-MAP-CALLBACK - Trace mapping of comment nodes to their text values
   */
  function commentToValue(c: any) {
    return c.value;
  }

  return comments.map(commentToValue).join(" ");
}

/**
 * Report missing @story annotation on a branch node.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-PARSING - Parse @story and @req annotations from branch comments
 */
export function reportMissingStory(
  context: Rule.RuleContext,
  node: any,
  options: {
    indent: string;
    insertPos: number;
    storyFixCountRef: { count: number };
  },
): void {
  const { indent, insertPos, storyFixCountRef } = options;
  /**
   * Conditional branch deciding whether to offer an auto-fix for the missing story.
   * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
   * @req REQ-TRACEABILITY-FIX-DECISION - Trace decision to provide fixer for missing @story
   */
  if (storyFixCountRef.count === 0) {
    /**
     * Fixer that inserts a default @story annotation above the branch.
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-TRACEABILITY-FIX-ARROW - Trace fixer function used to insert missing @story
     */
    function insertStoryFixer(fixer: any) {
      return fixer.insertTextBeforeRange(
        [insertPos, insertPos],
        `${indent}// @story <story-file>.story.md\n`,
      );
    }

    context.report({
      node,
      messageId: "missingAnnotation",
      data: { missing: "@story" },
      fix: insertStoryFixer,
    });
    storyFixCountRef.count++;
  } else {
    context.report({
      node,
      messageId: "missingAnnotation",
      data: { missing: "@story" },
    });
  }
}

/**
 * Report missing @req annotation on a branch node.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-PARSING - Parse @story and @req annotations from branch comments
 */
export function reportMissingReq(
  context: Rule.RuleContext,
  node: any,
  options: { indent: string; insertPos: number; missingStory: boolean },
): void {
  const { indent, insertPos, missingStory } = options;
  /**
   * Conditional branch deciding whether to offer an auto-fix for the missing req.
   * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
   * @req REQ-TRACEABILITY-FIX-DECISION - Trace decision to provide fixer for missing @req
   */
  if (!missingStory) {
    /**
     * Fixer that inserts a default @req annotation above the branch.
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-TRACEABILITY-FIX-ARROW - Trace fixer function used to insert missing @req
     */
    function insertReqFixer(fixer: any) {
      return fixer.insertTextBeforeRange(
        [insertPos, insertPos],
        `${indent}// @req <REQ-ID>\n`,
      );
    }

    context.report({
      node,
      messageId: "missingAnnotation",
      data: { missing: "@req" },
      fix: insertReqFixer,
    });
  } else {
    context.report({
      node,
      messageId: "missingAnnotation",
      data: { missing: "@req" },
    });
  }
}

/**
 * Compute annotation-related metadata for a branch node.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-PARSING - Parse @story and @req annotations from branch comments
 */
function getBranchAnnotationInfo(
  sourceCode: ReturnType<Rule.RuleContext["getSourceCode"]>,
  node: any,
): {
  missingStory: boolean;
  missingReq: boolean;
  indent: string;
  insertPos: number;
} {
  const text = gatherBranchCommentText(sourceCode, node);
  const missingStory = !/@story\b/.test(text);
  const missingReq = !/@req\b/.test(text);
  const indent =
    sourceCode.lines[node.loc.start.line - 1].match(/^(\s*)/)?.[1] || "";
  const insertPos = sourceCode.getIndexFromLoc({
    line: node.loc.start.line,
    column: 0,
  });

  return { missingStory, missingReq, indent, insertPos };
}

/**
 * Report missing annotations on a branch node.
 * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-PARSING - Parse @story and @req annotations from branch comments
 */
export function reportMissingAnnotations(
  context: Rule.RuleContext,
  node: any,
  storyFixCountRef: { count: number },
): void {
  const sourceCode = context.getSourceCode();

  const { missingStory, missingReq, indent, insertPos } =
    getBranchAnnotationInfo(sourceCode, node);

  const actions: Array<{ missing: boolean; fn: Function; args: any[] }> = [
    {
      missing: missingStory,
      fn: reportMissingStory,
      args: [context, node, { indent, insertPos, storyFixCountRef }],
    },
    {
      missing: missingReq,
      fn: reportMissingReq,
      args: [context, node, { indent, insertPos, missingStory }],
    },
  ];

  /**
   * Process a single action from the actions array.
   * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
   * @req REQ-TRACEABILITY-ACTIONS-FOREACH - Trace processing of actions array to report missing annotations
   */
  function processAction(item: {
    missing: boolean;
    fn: Function;
    args: any[];
  }) {
    /**
     * Callback invoked for each action to decide and execute reporting.
     * @story docs/stories/004.0-DEV-BRANCH-ANNOTATIONS.story.md
     * @req REQ-TRACEABILITY-FOR-EACH-CALLBACK - Trace callback handling for each action item
     */
    if (item.missing) {
      item.fn(...item.args);
    }
  }

  actions.forEach(processAction);
}

/**
 * Shared @req detection helpers used by annotation-checker utilities.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQ-DETECTION - Detect @req markers around function-like nodes
 */
import {
  FALLBACK_WINDOW,
  LOOKBACK_LINES,
} from "../rules/helpers/require-story-io";

/**
 * Predicate helper to check whether a comment contains a requirement annotation.
 * Treats both @req and @implements annotations as satisfying requirement presence checks.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-ANNOTATION-REQ-DETECTION - Detect @req tag inside a comment
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Accept @implements as requirement annotation
 */
function commentContainsReq(c: any): boolean {
  return (
    c &&
    typeof c.value === "string" &&
    (c.value.includes("@req") || c.value.includes("@implements"))
  );
}

/**
 * Line-based helper adapted from linesBeforeHasStory to detect requirement annotations.
 * Lines containing either @req or @implements are treated as annotated.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQ-DETECTION - Detect @req in preceding source lines
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Accept @implements in preceding source lines
 */
function linesBeforeHasReq(sourceCode: any, node: any): boolean {
  const lines = sourceCode && sourceCode.lines;
  const startLine =
    node && node.loc && typeof node.loc.start?.line === "number"
      ? node.loc.start.line
      : null;

  // Guard against missing or malformed source/loc information before scanning.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION - Avoid false positives when sourceCode/loc is incomplete
  if (!Array.isArray(lines) || typeof startLine !== "number") {
    return false;
  }

  const from = Math.max(0, startLine - 1 - LOOKBACK_LINES);
  const to = Math.max(0, startLine - 1);

  // Scan each physical line in the configured lookback window for @req or @implements markers.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION - Search preceding lines for @req text
  // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Search preceding lines for @implements text
  for (let i = from; i < to; i++) {
    const text = lines[i];
    // When a line contains @req or @implements we treat the function as already annotated.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Detect @req marker in raw source lines
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Detect @implements marker in raw source lines
    if (
      typeof text === "string" &&
      (text.includes("@req") || text.includes("@implements"))
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Parent-chain helper adapted from parentChainHasStory to detect requirement annotations.
 * Accepts both @req and @implements in parent-chain comments as satisfying requirement presence.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @req REQ-ANNOTATION-REQ-DETECTION - Detect @req in parent-chain comments
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Accept @implements in parent-chain comments
 */
function parentChainHasReq(sourceCode: any, node: any): boolean {
  let p = node && node.parent;

  // Walk up the parent chain and inspect comments attached to each ancestor.
  // Accept both @req and @implements markers when local comments are absent.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION - Traverse parent nodes when local comments are absent
  // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Allow @implements to satisfy requirement on parents
  while (p) {
    const pComments =
      typeof sourceCode?.getCommentsBefore === "function"
        ? sourceCode.getCommentsBefore(p) || []
        : [];

    // Look for @req or @implements in comments immediately preceding each parent node.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Detect @req markers in parent comments
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Detect @implements markers in parent comments
    if (Array.isArray(pComments) && pComments.some(commentContainsReq)) {
      return true;
    }

    const pLeading = p.leadingComments || [];

    // Also inspect leadingComments attached directly to the parent node, accepting @req or @implements.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Detect @req markers in parent leadingComments
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Detect @implements markers in parent leadingComments
    if (Array.isArray(pLeading) && pLeading.some(commentContainsReq)) {
      return true;
    }

    p = p.parent;
  }
  return false;
}

/**
 * Fallback text window helper adapted from fallbackTextBeforeHasStory to detect requirement annotations.
 * Treats both @req and @implements in the fallback text window as requirement presence.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-ANNOTATION-REQ-DETECTION - Detect @req in fallback text window before node
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Accept @implements in fallback text window before node
 */
function fallbackTextBeforeHasReq(sourceCode: any, node: any): boolean {
  // Guard against unsupported sourceCode or nodes without a usable range.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION - Ensure we only inspect text when range information is available
  if (
    typeof sourceCode?.getText !== "function" ||
    !Array.isArray((node && node.range) || [])
  ) {
    return false;
  }
  const range = node.range;

  // Guard when the node range cannot provide a numeric start index.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION - Avoid scanning when range start is not a number
  if (!Array.isArray(range) || typeof range[0] !== "number") {
    return false;
  }
  try {
    const start = Math.max(0, range[0] - FALLBACK_WINDOW);
    const textBefore = sourceCode.getText().slice(start, range[0]);

    // Detect @req or @implements in the bounded text window immediately preceding the node.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Detect @req marker in fallback text window
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Detect @implements marker in fallback text window
    if (
      typeof textBefore === "string" &&
      (textBefore.includes("@req") || textBefore.includes("@implements"))
    ) {
      return true;
    }
  } catch {
    // Swallow detection errors to avoid breaking lint runs due to malformed source.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Treat IO/detection failures as "no annotation" instead of throwing
    /* noop */
  }
  return false;
}

/**
 * Helper to determine whether a JSDoc or any nearby comments contain a requirement annotation.
 * Treats both @req and @implements annotations as evidence of requirement coverage.
 * @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
 * @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
 * @req REQ-ANNOTATION-REQ-DETECTION - Determine presence of @req annotation
 * @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Accept @implements as requirement coverage
 */
export function hasReqAnnotation(
  jsdoc: any,
  comments: any[],
  context?: any,
  node?: any,
): boolean {
  try {
    const sourceCode =
      context && typeof context.getSourceCode === "function"
        ? context.getSourceCode()
        : undefined;

    // Prefer robust, location-based heuristics when sourceCode and node are available.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Use multiple heuristics to detect @req markers around the node
    // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS - Use multiple heuristics to detect @implements markers around the node
    if (sourceCode && node) {
      if (
        linesBeforeHasReq(sourceCode, node) ||
        parentChainHasReq(sourceCode, node) ||
        fallbackTextBeforeHasReq(sourceCode, node)
      ) {
        return true;
      }
    }
  } catch {
    // Swallow detection errors and fall through to simple checks.
    // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
    // @req REQ-ANNOTATION-REQ-DETECTION - Fail gracefully when advanced detection heuristics throw
  }

  // BRANCH requirement detection on JSDoc or comments, accepting both @req and @implements.
  // @story docs/stories/003.0-DEV-FUNCTION-ANNOTATIONS.story.md
  // @story docs/stories/010.2-DEV-MULTI-STORY-SUPPORT.story.md
  // @req REQ-ANNOTATION-REQ-DETECTION
  // @req REQ-REQUIRE-ACCEPTS-IMPLEMENTS
  return (
    (jsdoc &&
      typeof jsdoc.value === "string" &&
      (jsdoc.value.includes("@req") || jsdoc.value.includes("@implements"))) ||
    comments.some(commentContainsReq)
  );
}

/**
 * Utility functions for story path resolution and existence checking.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PATH-RESOLUTION - Resolve relative paths correctly and enforce configuration
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 */
import fs from "fs";
import path from "path";

/**
 * Describes the possible existence states for a checked path.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
export type StoryExistenceStatus = "exists" | "missing" | "fs-error";

/**
 * Result of checking a single candidate path.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
export interface StoryPathCheckResult {
  path: string;
  status: StoryExistenceStatus;
  error?: unknown;
}

/**
 * Aggregated existence result across multiple candidate paths.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
export interface StoryExistenceResult {
  candidates: string[];
  status: StoryExistenceStatus;
  matchedPath?: string;
  error?: unknown;
}

/**
 * Result of validating that a candidate path stays within the project boundary.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PROJECT-BOUNDARY - Validate files are within project boundaries
 */
export interface ProjectBoundaryCheckResult {
  candidate: string;
  isWithinProject: boolean;
}

/**
 * Validate that a candidate path stays within the project boundary.
 * This compares the resolved candidate path against the normalized cwd
 * prefix, ensuring that even when storyDirectories are misconfigured, we
 * never treat files outside the project as valid story references.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PROJECT-BOUNDARY - Validate files are within project boundaries
 */
export function enforceProjectBoundary(
  candidate: string,
  cwd: string,
): ProjectBoundaryCheckResult {
  const normalizedCwd = path.resolve(cwd);
  const normalizedCandidate = path.resolve(candidate);

  const isWithinProject =
    normalizedCandidate === normalizedCwd ||
    normalizedCandidate.startsWith(normalizedCwd + path.sep);

  return {
    candidate: normalizedCandidate,
    isWithinProject,
  };
}

/**
 * Internal helper to reset the filesystem existence cache. This is primarily
 * intended for tests that need to run multiple scenarios with different
 * mocked filesystem behavior without carrying over cached results.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PERFORMANCE-OPTIMIZATION - Allow safe cache reset in tests to avoid stale entries
 */
export function __resetStoryExistenceCacheForTests(): void {
  fileExistStatusCache.clear();
}

/**
 * Build candidate file paths for a given story path.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PATH-RESOLUTION - Resolve relative paths correctly and enforce configuration
 */
export function buildStoryCandidates(
  storyPath: string,
  cwd: string,
  storyDirs: string[],
): string[] {
  const candidates: string[] = [];
  // When the story path is already explicitly relative, resolve it only against the current working directory.
  // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
  // @req REQ-PATH-RESOLUTION - Preserve explicit relative story path semantics when building candidate locations
  if (storyPath.startsWith("./") || storyPath.startsWith("../")) {
    candidates.push(path.resolve(cwd, storyPath));
  } else {
    // For bare paths, first try resolving directly under the current working directory.
    // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
    // @req REQ-PATH-RESOLUTION - Attempt direct resolution from cwd before probing configured story directories
    candidates.push(path.resolve(cwd, storyPath));
    // Probe each configured story directory for a matching story filename.
    // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
    // @req REQ-PATH-RESOLUTION - Expand search across configured storyDirectories while staying within project
    for (const dir of storyDirs) {
      candidates.push(path.resolve(cwd, dir, path.basename(storyPath)));
    }
  }
  return candidates;
}

/**
 * Cache of filesystem existence checks keyed by absolute path.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
const fileExistStatusCache = new Map<string, StoryPathCheckResult>();

/**
 * Check a single candidate path, with caching and robust error handling.
 * All filesystem interactions are wrapped in try/catch and never throw.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
function checkSingleCandidate(candidate: string): StoryPathCheckResult {
  const cached = fileExistStatusCache.get(candidate);
  // Reuse any cached filesystem result to avoid redundant disk IO for the same candidate.
  // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
  // @req REQ-PERFORMANCE-OPTIMIZATION - Short-circuit on cached existence checks
  if (cached) {
    return cached;
  }

  let result: StoryPathCheckResult;

  try {
    const exists = fs.existsSync(candidate);
    // When the path does not exist at all, record a simple "missing" status.
    // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
    // @req REQ-FILE-EXISTENCE - Distinguish non-existent story paths from other failure modes
    if (!exists) {
      result = { path: candidate, status: "missing" };
    } else {
      const stat = fs.statSync(candidate);
      // Treat existing regular files as valid story candidates; other entry types are considered missing.
      // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
      // @req REQ-FILE-EXISTENCE - Only regular files may satisfy a story path reference
      if (stat.isFile()) {
        result = { path: candidate, status: "exists" };
      } else {
        // Path exists but is not a file; treat as missing for story purposes.
        result = { path: candidate, status: "missing" };
      }
    }
  } catch (error) {
    // Any filesystem error is captured and surfaced as an fs-error status instead of throwing.
    // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
    // @req REQ-ERROR-HANDLING - Represent filesystem failures as fs-error results while keeping callers resilient
    result = { path: candidate, status: "fs-error", error };
  }

  fileExistStatusCache.set(candidate, result);
  return result;
}

/**
 * Aggregate existence status across multiple candidate paths.
 * Returns the first successful match (`exists`), or, if none exist,
 * the first filesystem error encountered. If there are only missing
 * candidates, returns a missing status.
 *
 * This function never throws and is the preferred richer API for callers
 * that need more than a boolean.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
export function getStoryExistence(candidates: string[]): StoryExistenceResult {
  let firstFsError: StoryPathCheckResult | undefined;

  for (const candidate of candidates) {
    const res = checkSingleCandidate(candidate);

    // As soon as a candidate file is confirmed to exist, return a successful existence result.
    // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
    // @req REQ-FILE-EXISTENCE - Prefer the first positively-matched story file
    if (res.status === "exists") {
      return {
        candidates,
        status: "exists",
        matchedPath: res.path,
      };
    }

    // Remember the first filesystem error so callers can inspect a representative failure if no files exist.
    // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
    // @req REQ-ERROR-HANDLING - Surface a single representative filesystem error without failing fast
    if (res.status === "fs-error" && !firstFsError) {
      firstFsError = res;
    }
  }

  // Prefer reporting a filesystem error over a generic missing status when at least one candidate failed to read.
  // @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
  // @req REQ-ERROR-HANDLING - Distinguish IO failures from simple "missing" results in existence checks
  if (firstFsError) {
    return {
      candidates,
      status: "fs-error",
      error: firstFsError.error,
    };
  }

  return {
    candidates,
    status: "missing",
  };
}

/**
 * Check if any of the provided file paths exist.
 * Handles filesystem errors (e.g., EACCES) gracefully by treating them as non-existent
 * and never throwing.
 *
 * Internally delegates to the richer status-based helper while preserving the
 * original boolean-only API for backwards compatibility.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
export function storyExists(paths: string[]): boolean {
  const result = getStoryExistence(paths);
  return result.status === "exists";
}

/**
 * Normalize a story path to candidate absolute paths and check existence.
 * Filesystem errors are handled via the status-aware helper, which suppresses
 * exceptions and treats such cases as non-existent for the boolean flag while
 * still surfacing error details in the status field.
 *
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-PATH-RESOLUTION - Resolve relative paths correctly and enforce configuration
 * @req REQ-FILE-EXISTENCE - Validate that story file paths reference existing files
 * @req REQ-ERROR-HANDLING - Handle filesystem errors gracefully without throwing
 * @req REQ-PERFORMANCE-OPTIMIZATION - Cache filesystem checks to avoid redundant work
 */
export function normalizeStoryPath(
  storyPath: string,
  cwd: string,
  storyDirs: string[],
): {
  candidates: string[];
  exists: boolean;
  existence: StoryExistenceResult;
} {
  const candidates = buildStoryCandidates(storyPath, cwd, storyDirs);
  const existence = getStoryExistence(candidates);
  const exists = existence.status === "exists";
  return { candidates, exists, existence };
}

/**
 * Check if the provided path is absolute.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-SECURITY-VALIDATION - Prevent absolute path usage
 */
export function isAbsolutePath(p: string): boolean {
  return path.isAbsolute(p);
}

/**
 * Check for path traversal patterns.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal
 */
export function containsPathTraversal(p: string): boolean {
  const normalized = path.normalize(p);
  return normalized.split(path.sep).includes("..");
}

/**
 * Determine if a path is unsafe due to traversal or being absolute.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal and absolute path usage
 */
export function isTraversalUnsafe(p: string): boolean {
  return isAbsolutePath(p) || containsPathTraversal(p);
}

/**
 * Validate that the story file has an allowed extension.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-SECURITY-VALIDATION - Enforce allowed file extensions
 */
export function hasValidExtension(p: string): boolean {
  return p.endsWith(".story.md");
}

/**
 * Determine if a story path is unsafe due to traversal, being absolute, or invalid extension.
 * @story docs/stories/006.0-DEV-FILE-VALIDATION.story.md
 * @req REQ-SECURITY-VALIDATION - Prevent path traversal, absolute path usage, and enforce allowed file extensions
 */
export function isUnsafeStoryPath(p: string): boolean {
  return isTraversalUnsafe(p) || !hasValidExtension(p);
}

