  const fallbackFn = isFirstArgFn
    ? (storyAnnotationOrFallbackFn as (_source: any, _node: any) => boolean)
    : maybeFallbackFn!;

  const pre = `/* ${storyAnnotation} */\n`;
  const rest = "function y() {}";
